# -*- coding: utf-8 -*-
"""English translations, batch 17 (40 figures)."""
EN = {
"底米丢": dict(lesson="Interests threatened, inciting a whole city",
 summary="The silversmith of Ephesus who incited a riot against Paul.",
 witness="Demetrius was a silversmith of Ephesus who made silver shrines of Artemis. Because Paul's preaching led people to forsake idols, his business suffered, so he incited his trade to cry 'Great is Artemis of the Ephesians,' throwing the whole city into confusion. When the gospel touches people's purse, opposition often comes fiercest—under a religious banner, what he guarded was in fact his gain.",
 follow=[],
 caution=["Under a religious pretext, in fact guarding private interest","Inciting the crowd's emotions, creating confusion"],
 applications=["Examine: when I oppose something, is it for truth or for private gain?","Don't guard your own interest under a spiritual banner","Neither incite nor be incited into group frenzy"],
 prayer="Lord, Demetrius incited a riot under a religious pretext for private gain. Make me honestly face my own motives, not guarding self-interest under a spiritual banner, nor swept along by group frenzy. Amen."),
"亚里达古": dict(lesson="A faithful companion sharing in affliction",
 summary="A Macedonian, Paul's faithful companion and fellow prisoner.",
 witness="Aristarchus was a Macedonian, Paul's faithful companion. He was seized with Paul in the Ephesus riot, accompanied Paul all the way by ship to Rome, and even became Paul's 'fellow prisoner.' From the storm to the prison, he stayed alongside—a true companion is the one who does not leave in affliction.",
 follow=["Staying alongside without leaving in affliction","Willingly sharing the risk of the one he followed"],
 caution=[],
 applications=["Don't leave a friend or co-worker in affliction","Willingly share risk and cost with people","Be the faithful companion of the 'fellow prisoner' kind"],
 prayer="Lord, Aristarchus stayed with Paul all through affliction. Make me a faithful companion who does not leave in affliction, willingly sharing risk, walking with people through their lows. Amen."),
"所巴特": dict(lesson="A Berean who traveled with Paul",
 summary="A Berean, Paul's companion.",
 witness="Sopater was a Berean, one of Paul's companions on his last journey. The Bereans were known for 'examining the Scriptures daily, to see whether these things were so,' and Sopater was very likely fruit of that group, now a co-worker accompanying the apostle and sharing in missions.",
 follow=["Committing to service on a foundation of examining Scripture","Willingly a companion on the missionary journey"],
 caution=[],
 applications=["Lay a foundation for service with solid Bible study","Willingly accompany and support gospel workers","Be a reliable fellow traveler in the team"],
 prayer="Lord, Sopater went from examining Scripture in Berea to being Paul's companion. Root me in solid truth, willingly accompanying and sharing in Your gospel work. Amen."),
"西公都": dict(lesson="A Thessalonian who walked the journey with Paul",
 summary="A Thessalonian, Paul's companion.",
 witness="Secundus was a Thessalonian, one of Paul's companions on his last journey, traveling with Aristarchus and others. He has no astonishing deeds, yet was one of the faithful co-workers who accompanied and escorted the apostle all the way. To walk with someone to the end is itself a kind of faithfulness.",
 follow=["Willingly a faithful companion on the missionary journey","Accompanying and escorting God's worker"],
 caution=[],
 applications=["Willingly accompany and escort those who serve the Lord","Be a reliable fellow traveler in the team","Value the faithfulness of 'walking all the way together'"],
 prayer="Lord, Secundus accompanied Paul's whole journey. Make me a faithful companion, accompanying and escorting Your workers, serving You with the faithfulness of walking to the end. Amen."),
"特罗非摩": dict(lesson="Co-workers fall ill too; service has its limits",
 summary="An Ephesian, Paul's companion.",
 witness="Trophimus was an Ephesian, Paul's companion, who was once mistaken as being brought into the temple, triggering the riot in Jerusalem. Later Paul said, 'I left Trophimus sick at Miletus.' Even the mighty Paul did not heal his co-worker's illness—service has limits God has set, and the sovereignty to heal is God's.",
 follow=["Faithfully walking alongside both in health and in weakness"],
 caution=["Not making 'healing' the measure of faith or grace"],
 applications=["Accept that both service and the body have limits; sovereignty is God's","Support one another when a co-worker is ill or weak","Don't doubt God's love because an illness was not healed"],
 prayer="Lord, even Paul left the sick Trophimus at Miletus. Make me accept the limits of service, give the sovereignty to heal to You, and still support and faithfully walk alongside in weakness. Amen."),
"犹推古": dict(lesson="Fell asleep and fell down, yet the Lord showed grace",
 summary="The young man who fell asleep during the sermon, fell, and was raised by Paul.",
 witness="Eutychus was a young man; as Paul preached until midnight at Troas, he sank into deep sleep on the windowsill, fell from the third floor, and was picked up dead. Paul went down and fell on him, and he came to life, and the people were greatly comforted. Weak and embarrassed as he was, the Lord's grace still came to him.",
 follow=[],
 caution=["Strive to stay alert when hearing the word, not indulging drowsiness"],
 applications=["Strive to stay alert when hearing the word and drawing near to God","Even in weakness and lapse, look to the Lord's grace","Bear with the weak among us in gatherings"],
 prayer="Lord, Eutychus fell asleep and fell down, yet You showed grace and brought him back to life. Help me stay alert when hearing the word, and trust Your grace and support even in weakness. Amen."),
"腓力的四个女儿": dict(lesson="One home, four daughters who prophesied",
 summary="Four virgin sisters who prophesied.",
 witness="Philip's four daughters were all virgins who all prophesied. Philip the evangelist raised four daughters used by the Spirit to proclaim God's word. A godly home open to God can be fertile soil for spiritual gifts—four children used by God together, what a blessing.",
 follow=["Open to God's gifts in a godly home","Willingly used by the Spirit to proclaim God's word"],
 caution=[],
 applications=["Build a home where children's spiritual gifts can grow","Encourage everyone in the home to be used by God","Value and support the sisters' spiritual gifts"],
 prayer="Lord, Philip's four daughters all prophesied. Make my home fertile soil for spiritual gifts, that everyone in it be open to You and used by You. Amen."),
"革老丢吕西亚": dict(lesson="Lawfully guarding, rescuing people from chaos",
 summary="The tribune who protected Paul.",
 witness="Claudius Lysias was the tribune in Jerusalem. When the crowd tried to beat Paul to death, he stepped in to rescue him; learning that over forty men had sworn to kill Paul, he sent a heavy guard that night to escort Paul safely to Caesarea. By Roman law, he protected Paul's life again and again. Upholding the law justly can also be a shield protecting the innocent.",
 follow=["Lawfully and justly guarding the innocent's life","Acting decisively to rescue people in crisis"],
 caution=[],
 applications=["Protect the innocent within your authority","Uphold the law justly, neither bending to favor nor breaking it","Act decisively in crisis, rather than stand by"],
 prayer="Lord, Claudius Lysias lawfully rescued Paul several times. Make me justly guard the innocent within my authority, acting decisively in crisis, a shield protecting people. Amen."),
"腓力斯": dict(lesson="Heard the word, yet waited for a 'convenient time'",
 summary="The Roman governor who delayed judging Paul.",
 witness="Felix was the Roman governor. As Paul spoke of justice, self-control, and the judgment to come, he was afraid and said 'go away for now; when I have an opportunity I will call you'; he also hoped Paul would give him money, and kept him in prison two years. Touched by truth yet ever delaying, he waited 'a convenient time' into an eternal missed chance.",
 follow=[],
 caution=["Touched by truth yet repeatedly delaying response","Coveting gain, shelving the decision indefinitely"],
 applications=["Don't delay responding to truth to 'a convenient time'","Don't let gain and delay steal the chance to repent","When touched by God's word, respond at once"],
 prayer="Lord, Felix was touched by truth yet delayed and coveted gain. Make me not delay responding to You again and again, but turn back and obey while the prompting is still here. Amen."),
"土西拉": dict(lesson="Heard the word, yet stayed where she was",
 summary="Felix's Jewish wife.",
 witness="Drusilla was the Jewish wife of Governor Felix. When Paul spoke before them of 'justice, self-control, and the judgment to come,' Felix was afraid. Though a Jew, close to the truth, she joined her husband in shelving Paul. Even those closest to truth may never respond.",
 follow=[],
 caution=["Close to truth, yet never responding","Joining those around her in shelving the decision she ought to make"],
 applications=["When you've heard truth, respond in time, not shelve it","Don't miss truth because of the indifference of those around you","With the best access, all the more seize the chance to draw near to God"],
 prayer="Lord, Drusilla was close to truth yet did not respond. Make me respond in time when I hear Your word, not miss it through others' indifference, not shelving the decision again and again. Amen."),
"非斯都": dict(lesson="Seeking justice, yet compromising to please people",
 summary="The governor who succeeded Felix in questioning Paul.",
 witness="Festus was the governor who succeeded Felix. Finding no crime worthy of death in Paul, he could have released him, yet 'wishing to do the Jews a favor' he asked Paul if he would be tried in Jerusalem, forcing Paul to appeal to Caesar. He also loudly said Paul was 'out of his mind.' Knowing the innocent yet not upholding justice to please people is a common compromise of those in power.",
 follow=[],
 caution=["Knowing the innocent yet not upholding justice to please people","Slighting with 'out of his mind' a faith he could not understand"],
 applications=["Act justly, not compromising to please any side","Don't slight or mock a faith you don't understand","Hold a just judgment under pressure"],
 prayer="Lord, Festus knew Paul was innocent yet compromised to please people. Make me act justly, not compromise justice to please people, nor slight the truth I don't understand. Amen."),
"希律亚基帕一世": dict(lesson="The end of persecuting the church and stealing glory",
 summary="Who killed James, imprisoned Peter, and later was eaten by worms and died.",
 witness="Herod Agrippa I, to please the Jews, killed the apostle James and went on to seize Peter. Later, amid the crowd's cry 'this is the voice of a god,' he gladly accepted it, not giving glory to God, and was at once struck by worms and died. Persecuting God's church and stealing God's glory, judgment follows.",
 follow=[],
 caution=["Persecuting and killing God's servants to please people","Coveting human praise, taking glory for himself"],
 applications=["Don't oppose God's work to please anyone","Give all praise and glory to God","Beware the spiritual danger when 'lifted up by people'"],
 prayer="Lord, Agrippa I persecuted the church and stole glory, and was at once judged. Make me not oppose Your work to please people, but give all glory to You alone. Amen."),
"希律亚基帕二世": dict(lesson="Almost is not the same as truly believing",
 summary="The king who heard Paul's defense.",
 witness="Herod Agrippa II, hearing Paul's defense, said: 'In a short time would you persuade me to be a Christian!' Touched by truth, he stopped at 'almost.' He admitted Paul was innocent, yet made no decision for his own soul. The last step toward God is sometimes the hardest to take.",
 follow=[],
 caution=["Touched by truth, yet always stopping at 'almost'","Admiring the gospel intellectually, yet unwilling to commit"],
 applications=["Don't stop at the edge of 'almost believing'; make a decision","When touched by truth, respond fully","Pray for those 'not far from God' who haven't decided"],
 prayer="Lord, Agrippa II almost believed, yet finally halted. Don't let me stop at the edge of 'almost'; make me respond fully to You and commit to You. Amen."),
"百尼基": dict(lesson="Accompanying the king to hear the word, yet only a passerby",
 summary="Sister of Agrippa II.",
 witness="Bernice was the sister of Herod Agrippa II, who came with her brother 'with great pomp' to hear Paul's defense. She witnessed that powerful plea and heard the gospel, yet like the pomp, came and went, leaving no response. To have heard and seen is not the same as to have believed.",
 follow=[],
 caution=["Treating the gospel with a spectator's, show-off mindset","Hearing yet not responding, passing by"],
 applications=["Don't treat truth with a bystander's, spectacle-seeking mindset","When you've heard the gospel, respond seriously, not be a passerby","Examine: have I truly believed, or only heard?"],
 prayer="Lord, Bernice heard Paul's defense yet was only a passerby. Make me not treat Your truth as a bystander, but truly respond on hearing, not passing by. Amen."),
"犹流": dict(lesson="A centurion who treated a prisoner well",
 summary="The centurion who escorted Paul to Rome and treated him well.",
 witness="Julius was a centurion of the imperial regiment, ordered to escort the prisoner Paul to Rome. Along the way he treated Paul kindly, allowing him to go to friends to be cared for; and in the shipwreck, to save Paul, he stopped the soldiers' plan to kill the prisoners. A dutiful officer treated the prisoner he escorted with humanity and goodwill.",
 follow=["Treating people with humanity and goodwill in his duty","Stepping forth to guard the innocent when he should"],
 caution=[],
 applications=["Treat those in your charge with goodwill and humanity in your duties","Step forward when the weak should be guarded","Let duty and mercy go together"],
 prayer="Lord, Julius treated Paul kindly and saved his life. Make me treat people with humanity in my duties, stepping forth to guard the innocent, dutiful yet merciful. Amen."),
"部百流": dict(lesson="Receiving strangers in affliction",
 summary="The chief man of Malta who hosted Paul.",
 witness="Publius was the chief man of the island of Malta. When Paul was shipwrecked and drifted to the island, he warmly hosted the party for three days; and Paul prayed for and healed his father who had fever and dysentery, and all the sick of the island came and were healed. One hosting after a shipwreck became the occasion for the gospel to reach the whole island. A door of hospitality opened to strangers, God can greatly use.",
 follow=["Warmly receiving shipwrecked strangers","Becoming the occasion of the gospel reaching by hospitality"],
 caution=[],
 applications=["Open the door of hospitality to the stranded and the stranger","Trust God can greatly use one act of kind hospitality","Convey God's love in encounters amid affliction"],
 prayer="Lord, Publius received the shipwrecked Paul, and the gospel reached the whole island. Make me open my door to stranded strangers, trusting one act of hospitality can be a channel of Your grace. Amen."),
"马利亚（罗马教会）": dict(lesson="Toiling much for the brothers and sisters",
 summary="A sister who toiled much for the believers in Rome.",
 witness="She is the Mary Paul greeted in Romans, called 'who has worked hard for you.' She is not any famous Mary, only a sister in the Roman church who toiled diligently for the members. 'Worked hard for you'—this is the apostle's most concrete commendation of a quiet servant.",
 follow=["Willingly toiling much for the brothers and sisters","Quietly serving everyone in the community"],
 caution=[],
 applications=["Willingly toil diligently for the members near you","Not for recognition, but toil for the good of all","Value the service of 'toiling for the brothers and sisters'"],
 prayer="Lord, this Mary toiled much for all the members. Make me too willingly toil diligently for the brothers and sisters, quietly serving in the community, not seeking people's praise. Amen."),
"尼利亚的姊妹": dict(lesson="Even 'the sister' is remembered together",
 summary="A saint Paul greeted.",
 witness="She was Nereus' sister, mentioned with her brother in Paul's greeting, with not even her name recorded separately, called only 'Nereus' sister.' Yet the Spirit still recorded her in Scripture. In God's eyes, the most unremarkable, the most 'incidentally' mentioned, is equally seen and remembered.",
 follow=["Still seen by God in the most unremarkable place"],
 caution=[],
 applications=["Trust that however unremarkable you are, God sees and remembers","Don't despise your 'incidental,' hidden service","Go and see and treasure those easily overlooked"],
 prayer="Lord, You remembered even 'Nereus' sister.' Make me firmly trust that however unremarkable I am, You see me, and make me go see and treasure those easily overlooked. Amen."),
"德丢": dict(lesson="The hand that writes also serves",
 summary="The one who wrote down Romans as Paul's scribe.",
 witness="Tertius was the one who wrote Romans as Paul's scribe; at the letter's end he inserted: 'I Tertius, who wrote this letter, greet you in the Lord.' This history-changing letter owed labor to his pen. Behind-the-scenes, technical service (scribing, paperwork) is equally precious service.",
 follow=["Taking part in God's work through behind-the-scenes, technical service","Faithful in an inconspicuous post"],
 caution=[],
 applications=["Serve God with your skills (writing, technical work, etc.)","Value the worth of behind-the-scenes, supporting service","Hold a serving heart even in unsigned work"],
 prayer="Lord, Tertius took part in writing Romans with his pen. Make me serve You behind the scenes with my skills, serving faithfully in inconspicuous posts. Amen."),
"该犹（马其顿人）": dict(lesson="A companion caught up in the storm",
 summary="Paul's Macedonian companion, seized in the Ephesus riot.",
 witness="Gaius was a Macedonian, a fellow traveler of Paul, who with Aristarchus was seized by the crowd in the Ephesus riot and dragged into the theater. He was caught up in danger because he traveled with Paul. Following and traveling with God's worker sometimes means bearing the storms that come with it.",
 follow=["Willingly traveling with God's worker, and sharing the storm"],
 caution=[],
 applications=["When following and traveling, be ready to share the risk too","Watch over one another with companions amid the storm","Don't quit traveling together because of the cost of being caught up"],
 prayer="Lord, Gaius was caught up in the riot for traveling with Paul. Make me willingly travel and share the storm with Your worker, watching over one another in danger, not quitting easily. Amen."),
"该犹（约翰三书）": dict(lesson="Walking in truth, receiving those from afar",
 summary="The one John loved, who faithfully received the brothers.",
 witness="Gaius was the recipient of 3 John, whom John 'loved in truth.' He 'walked in truth' and faithfully received the traveling preachers going out for the Name, strangers to him, in sharp contrast to Diotrephes who would not receive people. Love and truth went together in him—this is why John rejoiced greatly over him.",
 follow=["Walking in truth, word and deed consistent","Faithfully receiving the workers who go out for the Name"],
 caution=[],
 applications=["Let your love and truth be shown together","Receive and supply those who travel for the gospel","Don't learn Diotrephes' exclusion, but Gaius' hospitality"],
 prayer="Lord, Gaius walked in truth and faithfully received those from afar. Make my love and truth go together, gladly receiving the workers who travel for Your Name, the kind John delighted in. Amen."),
"括土": dict(lesson="A brother in one word of greeting",
 summary="A brother mentioned in Paul's greeting.",
 witness="Quartus was a 'brother' mentioned in the greeting at the end of Paul's letter. About him, Scripture leaves only this one identity and name. Yet the word 'brother' is precious enough—in Christ, he belongs to one family with the apostle and all the saints.",
 follow=["Belonging to one family with all the saints as a 'brother'"],
 caution=[],
 applications=["Treasure the identity of 'being brothers together in Christ'","Treat those in the Lord with brotherly affection","Trust that simply 'being a brother in the Lord' is grace"],
 prayer="Lord, Quartus is remembered by the name 'brother.' Make me treasure the identity of being brothers and sisters together in You, treating those in the Lord with real brotherly love. Amen."),
"亚利多布家的人": dict(lesson="A whole household to the Lord, remembered together",
 summary="A household Paul greeted.",
 witness="The household of Aristobulus is a family Paul greeted in Romans. The apostle did not greet just one person, but remembered a whole 'household' together. The gospel often reaches a family, a community; in the Lord, the whole family is cared for and shown grace together.",
 follow=["Hoping and leading the whole family into the Lord together","Living out and carrying the faith at the family level"],
 caution=[],
 applications=["Pray and strive for your whole family to come to the Lord","Make faith a shared reality for the whole family","Treasure the grace of 'a household remembered in the Lord'"],
 prayer="Lord, the household of Aristobulus is remembered together. Make the gospel reach my whole family, that we come to You together, shown grace and remembered together in the Lord. Amen."),
"拿其数家的人": dict(lesson="A household in the Lord, cared for by the apostle",
 summary="A household in the Lord whom Paul greeted.",
 witness="The household of Narcissus is a family Paul greeted in Romans, specially noted as 'those in the Lord.' Within a large household (Narcissus himself may not have believed), there was a group belonging to the Lord. Even in an unbelieving environment, they still gathered in the Lord and were remembered by the apostle—a community of God can exist anywhere.",
 follow=["Still gathering in the Lord even in an unbelieving environment","Being a small community of God within a larger environment"],
 caution=[],
 applications=["Still hold your faith in an unbelieving family or workplace","Support one another and gather with members in similar situations","Trust a community of the Lord can exist anywhere"],
 prayer="Lord, those in the Lord in the household of Narcissus were also remembered. Make me hold my faith even in an unbelieving environment, gathering with members, being Your community. Amen."),
"鲁孚的母亲": dict(lesson="A mother's heart treating people as her own",
 summary="A sister who treated Paul like a mother.",
 witness="She was Rufus' mother, of whom Paul said 'she has been a mother to me.' She evidently cared for Paul with motherly care—cooking, mending, asking after his welfare. These unremarkable motherly cares warmed a much-traveled apostle, remembered by him all his life. Motherly love is the most ordinary and most remembered service.",
 follow=["Caring for God's worker with motherly care","Warming and supplying people in life's small details"],
 caution=[],
 applications=["Care for those near you with a mother's attentiveness","Serve God's workers in small things like food and daily needs","Count plain care as precious service"],
 prayer="Lord, Rufus' mother cared for Paul with a mother's love. Make me too serve people with such plain, warm care, supplying and tending Your workers in life's small details. Amen."),
"革来氏家里的人": dict(lesson="For the sake of unity, truthfully reporting strife",
 summary="Those who reported the Corinthian strife to Paul.",
 witness="Chloe's household told Paul the truth of the factional strife in the Corinthian church, prompting him to write to exhort and safeguard unity. They were not stirring up gossip, but out of concern for the church truthfully reflected the problem, so the strife could be healed. Honestly reflecting a problem for unity is entirely different from spreading rumors.",
 follow=["Out of concern for the community, truthfully reflecting the problem","Speaking for unity, not to spread gossip"],
 caution=["Reflecting a problem must be out of love and for building up, not gossip"],
 applications=["For the community's good, honestly reflect problems that should be handled","Distinguish 'reflecting for building up' from 'spreading gossip'","Make the motive of your speech the fostering of unity"],
 prayer="Lord, Chloe's household truthfully reported the strife for unity. Make my speech be out of love and for building up, honestly reflecting problems for the community's unity, not spreading gossip. Amen."),
"所提尼": dict(lesson="From opponent to co-worker, grace turns a life around",
 summary="The brother who co-signed a letter with Paul.",
 witness="Sosthenes was originally the ruler of the synagogue in Corinth, once beaten before the judgment seat; yet later he became a Christian, co-signing with Paul the letter to the Corinthian church. God's grace can turn a former opponent into a present co-worker—no one is beyond the reach of grace.",
 follow=["Turning around to become a co-worker after experiencing grace","Laying down his old identity, committing to the gospel"],
 caution=["Not judging by a person's past identity that he cannot change"],
 applications=["Trust God can turn around anyone, including a former opponent","Hold hope for the 'change' of yourself or others","After experiencing grace, devote yourself to service"],
 prayer="Lord, You turned the synagogue ruler Sosthenes into Paul's co-worker. Make me trust the turning power of Your grace, not despising anyone, and willingly be renewed and used by You. Amen."),
"司提反一家": dict(lesson="The firstfruits, devoted to serving",
 summary="The firstfruits of Achaia, devoted to serving the saints.",
 witness="The household of Stephanas was the 'firstfruits of Achaia,' whom Paul baptized. They 'devoted themselves to the service of the saints,' and Paul urged everyone to submit to such people. A family of one heart made serving all the saints their singular resolve—what a beautiful whole-family service.",
 follow=["A whole family of one heart, devoted to serving the saints","Being servants worthy of submission and imitation in the community"],
 caution=[],
 applications=["Let your whole family devote itself to serving God's community","Make serving people your singular resolve","Respect and follow those who devote themselves to serving"],
 prayer="Lord, the household of Stephanas devoted itself to serving the saints. Make me and my family of one heart serve Your community, making serving people our singular resolve, glorifying Your name. Amen."),
"福徒拿都": dict(lesson="Coming from afar to supply, bringing gladness",
 summary="A co-worker who came from Corinth to see Paul.",
 witness="Fortunatus came from Corinth with the household of Stephanas and Achaicus to see Paul, 'supplying what was lacking on your part,' refreshing Paul's heart. Their coming was itself a comfort, their service filled the gap. Paul urged everyone to honor such people.",
 follow=["Taking initiative to go supply another's lack","Bringing comfort by his visit and service"],
 caution=[],
 applications=["Take initiative to visit and supply members' needs","Let your presence be a comfort to others","Honor those who quietly fill gaps and serve people"],
 prayer="Lord, Fortunatus came from afar to supply and refresh Paul. Make me take initiative to fill others' lacks, bringing comfort by visit and service. Amen."),
"亚该古": dict(lesson="Coming from far, refreshing people's hearts",
 summary="A co-worker who came with Fortunatus.",
 witness="Achaicus came from Corinth with the household of Stephanas and Fortunatus to see Paul, 'supplying what was lacking on your part,' refreshing the hearts of Paul and all. Their coming and service were like a timely comfort. Some people's very presence is an encouragement.",
 follow=["Supplying another's lack by visit and service","Being a comforter who refreshes people's hearts"],
 caution=[],
 applications=["Take initiative to visit and fill others' needs","Let your presence be an encouragement to others","Bring timely service when members are weary"],
 prayer="Lord, Achaicus' coming refreshed Paul's heart. Make me one who fills others' lacks and brings comfort, my visits an encouragement to people. Amen."),
"革勒免": dict(lesson="A co-worker whose name is in the book of life",
 summary="A co-worker who labored with Paul in Philippi.",
 witness="Clement was one of the co-workers in the Philippian church who 'labored together' with Paul. Paul said his name and the others' 'are in the book of life.' His deeds on earth may be little proclaimed, yet his name is recorded in that more important book in heaven—this is true glory.",
 follow=["Laboring together with people for the gospel","Valuing his name in heaven over proclamation on earth"],
 caution=[],
 applications=["Willingly labor together with people for the gospel","Take 'a name in the book of life' as the greatest comfort","Don't seek earthly fame, only to be remembered by God"],
 prayer="Lord, Clement labored with Paul, his name in the book of life. Make me willingly labor for the gospel, taking my name being recorded by You in heaven as my greatest glory and comfort. Amen."),
"宁法": dict(lesson="Offering the home as the church's meeting place",
 summary="A sister who hosted a church in her home.",
 witness="Nympha was a sister around Laodicea, and 'in her house' there was a church. She opened her own home so believers could gather to worship and fellowship. In an age without church buildings, it was such open homes, one after another, that held up the gatherings of the early church.",
 follow=["Opening her own home for believers to gather and fellowship","Serving God's community with her dwelling"],
 caution=[],
 applications=["Open your home and space to fellowship gatherings","Support the church with hospitality and a place","Value the worth of 'home gatherings' as service"],
 prayer="Lord, Nympha offered her home as the church's meeting place. Make me too willingly open all I have for members to gather and fellowship, serving Your community with my dwelling. Amen."),
"亚腓亚": dict(lesson="A sister remembered in the house church",
 summary="A sister greeted in Philemon.",
 witness="Apphia was a sister greeted at the opening of Philemon, very likely Philemon's wife, connected with the church in their home. She, with her family, received the church and took part in service. In the service where family and church intertwine, her name is solemnly mentioned.",
 follow=["Taking part with family in receiving and serving the church","Carrying the church's fellowship at the family level"],
 caution=[],
 applications=["Let your family take part in and support the church's fellowship","Serve the Lord of one heart with family","Value the form of service that is 'the church in the home'"],
 prayer="Lord, Apphia served the church with her family. Make my family too a place that carries fellowship and receives members, serving You of one heart with family. Amen."),
"耶数（犹士都）": dict(lesson="A faithful Jewish co-worker among the few",
 summary="Paul's Jewish co-worker.",
 witness="Jesus (also called Justus) was one of Paul's Jewish co-workers. Paul specially mentioned, 'of the circumcision these are the only fellow workers for the kingdom of God, and they have been a comfort to me.' When most of his countrymen drew away, he still stood with Paul—a faithful comfort among the few.",
 follow=["Still standing faithfully when most drew away","Being a comfort to a co-worker's heart"],
 caution=[],
 applications=["When most retreat, willingly be the faithful few","Be a comforter to weary co-workers","Don't drift with the crowd; stand firmly on the kingdom's side"],
 prayer="Lord, Justus among the few still co-labored with Paul and comforted him. Make me stand faithfully when most draw away, a comfort to the hearts of companions. Amen."),
"革勒士": dict(lesson="Sent to go, each to his own field",
 summary="A co-worker who went to Galatia.",
 witness="Crescens was Paul's co-worker; Paul mentioned at his letter's end, 'Crescens has gone to Galatia.' Co-workers were sent to different places as needed. His leaving was not abandonment, but being assigned to work elsewhere. The spread of the gospel needs just such people willing to go to every field.",
 follow=["Willingly sent to the field where needed","Each in his place, extending the borders of the gospel"],
 caution=[],
 applications=["Willingly be sent by God to where you are needed","Don't cling to one place; be willing to work in every place","See the dispersion of co-workers as the expansion of the gospel's borders"],
 prayer="Lord, Crescens was sent to work in Galatia. Make me willingly be sent by You to where I am needed, each in his place, extending the borders of Your gospel together. Amen."),
"加布": dict(lesson="One who keeps things in store for a co-worker",
 summary="The one at whose house Paul left his cloak.",
 witness="Carpus was a brother in Troas, at whose house Paul left his cloak, books, and parchments. One line, 'bring the cloak that I left with Carpus when you come,' shows us: he was a trustworthy person who kept what a co-worker needed in store. Reliable hospitality and safekeeping is also service.",
 follow=["Trustworthy, keeping in store well what a co-worker needs","Taking part in service by hospitality and safekeeping"],
 caution=[],
 applications=["Be a trustworthy, reliable person","Take part in God's work by hospitality, safekeeping, and logistics","Value the inconspicuous yet necessary 'logistics' service"],
 prayer="Lord, Paul left what he needed with Carpus. Make me a trustworthy, reliable person, faithfully taking part in Your work by hospitality and logistics. Amen."),
"亚历山大（铜匠）": dict(lesson="Much opposition, God will surely repay",
 summary="The coppersmith who much opposed Paul.",
 witness="Alexander was a coppersmith who 'did much harm' to Paul, opposing the word preached. Paul warned Timothy to beware of him, saying 'the Lord will repay him according to his deeds.' One who knows the truth yet insists on opposing has set himself in the position of an enemy of God.",
 follow=[],
 caution=["Knowing the truth yet insisting on opposing and resisting","Hindering the gospel in many ways by his actions"],
 applications=["Don't stand on the side opposing truth and hindering the gospel","Be on guard against those who 'much oppose' truth","Leave vengeance to the Lord who repays justly"],
 prayer="Lord, the coppersmith Alexander much opposed Your truth. Make me never stand on the side resisting You, on guard against those who hinder the gospel, leaving vengeance to You. Amen."),
"亚历山大（以弗所人）": dict(lesson="A man pushed to the eye of the storm",
 summary="The Jew pushed forward in the Ephesus riot.",
 witness="Alexander was the man the Jews pushed forward in the Ephesus riot, wanting to make a defense, but because he was a Jew, the crowd, on seeing him, shouted for two hours. He was caught up in a chaos not his own, and could not even speak. In turmoil, people are often not their own masters.",
 follow=[],
 caution=["(Background) caught up in the crowd's shouting and chaos"],
 applications=["Stay clear-headed in group chaos, not joining the shouting","Don't be pushed by people into a storm you shouldn't be caught in","Discern in the noise what should and should not be said"],
 prayer="Lord, Alexander was caught in the noise of Ephesus. Make me stay clear-headed in group chaos, not echoing the crowd, not pushed by people into a storm I shouldn't be caught in. Amen."),
"腓吉路": dict(lesson="Abandoning in affliction, a grief",
 summary="The one who deserted Paul in Asia.",
 witness="Phygelus was one of those Paul mentioned, 'all who are in Asia turned away from me.' When Paul was imprisoned and most needed support, he chose to leave. Abandonment is not open hostility, but quietly withdrawing in affliction—this kind of shrinking back is equally grievous.",
 follow=[],
 caution=["Quietly withdrawing when another is in affliction and most needs help","Abandoning the one he should support, for self-protection"],
 applications=["Don't shrink back or abandon friends and co-workers in affliction","Examine whether you only travel together when it's 'safe'","Be a dependable person in affliction"],
 prayer="Lord, Phygelus abandoned Paul in his affliction. Make me not withdraw when people are in affliction, but be a dependable, non-abandoning person, walking with the suffering members to the end. Amen."),
"黑摩其尼": dict(lesson="One who withdrew together in affliction",
 summary="The one who, with Phygelus, deserted Paul.",
 witness="Hermogenes, with Phygelus, was one of the two named in Paul's saying 'all who are in Asia turned away from me.' At Paul's hardest, neediest time, he chose to withdraw. Abandonment is often not a dramatic betrayal, but quietly slipping away in affliction—equally grievous.",
 follow=[],
 caution=["Quietly slipping away when people are in affliction and most need help","Withdrawing with the crowd, unwilling to hold firm"],
 applications=["Hold firm without leaving when friends and co-workers suffer","Don't withdraw with the crowd; be dependable in affliction","Examine whether you only travel together in good times"],
 prayer="Lord, Hermogenes abandoned Paul in his affliction. Make me not withdraw when people suffer, but be one who holds firm and is dependable, walking with the suffering to the end. Amen."),
}
